Future<void> load() async {
  setState(() => loading = true);
  final body = await rootBundle.loadString('assets/big.json');
  final list = (jsonDecode(body) as List)
      .map((e) => Product.fromJson(e as Map<String, dynamic>))
      .toList();
  setState(() {
    products = list;
    loading = false;
  });
}
